// Regenerates test/fixtures/agent-fixtures.ts from the Foundry build of test/fixtures/sol:
//   docker run --rm -v "<abs>/services/bookrunner-agent/test/fixtures/sol:/work" -w /work \
//     -v bookrunner-svm:/root/.svm --entrypoint forge ghcr.io/foundry-rs/foundry:latest build
//   bun test/fixtures/gen-fixtures.ts
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const names = ["FixtureUSDC", "FixtureEngine", "FixtureAdapter", "FixtureDesk"];
const outDir = resolve(import.meta.dir, "sol/out/AgentFixtures.sol");
let src = "// generated by test/fixtures/gen-fixtures.ts from test/fixtures/sol (test-only contracts) — do not edit\n";
for (const n of names) {
  const j = JSON.parse(readFileSync(resolve(outDir, `${n}.json`), "utf8")) as { abi: unknown; bytecode: { object: string } };
  src += `export const ${n[0]!.toLowerCase()}${n.slice(1)} = {\n  abi: ${JSON.stringify(j.abi)} as const,\n  bytecode: "${j.bytecode.object}" as \`0x\${string}\`,\n};\n`;
}
writeFileSync(resolve(import.meta.dir, "agent-fixtures.ts"), src);
console.log("wrote agent-fixtures.ts");
